const toast=document.querySelector('#toast');
const showToast=(title,copy)=>{toast.querySelector('b').textContent=title;toast.querySelector('.toast-copy').textContent=copy;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),3500)};
async function api(path,options={}){const response=await fetch(path,{credentials:'include',...options,headers:{Accept:'application/json',...(options.body?{'Content-Type':'application/json'}:{}),...options.headers}});const data=response.status===204?null:await response.json().catch(()=>({}));if(!response.ok)throw new Error(data?.message||'Operación rechazada.');return data}
const login=document.querySelector('#adminLogin');const panel=document.querySelector('#reviewPanel');const list=document.querySelector('#verificationList');
async function load(){const rows=await api('/api/admin/verifications');login.hidden=true;panel.hidden=false;list.innerHTML=rows.length?rows.map(row=>`<article class="review-card" data-user="${row.user_id}"><div><h2>${escapeHtml(row.legal_name)}</h2><p><b>${escapeHtml(row.role)}</b> · ${escapeHtml(row.email)}</p><p>Referencia: ${escapeHtml(row.document_reference)}</p><p>Enviada: ${new Date(row.submitted_at).toLocaleString('es-CL')}</p></div><div class="review-actions"><textarea placeholder="Motivo obligatorio"></textarea><button data-status="verified">Aprobar ticket</button><button class="reject" data-status="rejected">Rechazar</button></div></article>`).join(''):'<p>No hay solicitudes pendientes.</p>';list.querySelectorAll('[data-status]').forEach(button=>button.addEventListener('click',()=>review(button)))}
async function review(button){const card=button.closest('.review-card');const reason=card.querySelector('textarea').value.trim();if(!reason)return showToast('Falta el motivo','Registra el fundamento de la decisión.');button.disabled=true;try{await api(`/api/admin/verifications/${card.dataset.user}/review`,{method:'POST',body:JSON.stringify({status:button.dataset.status,reason})});showToast('Decisión registrada','La cuenta y la bitácora fueron actualizadas.');await load()}catch(error){showToast('No se pudo revisar',error.message)}finally{button.disabled=false}}
document.querySelector('#adminLoginForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const body=Object.fromEntries(new FormData(form));try{await api('/api/auth/login',{method:'POST',body:JSON.stringify(body)});await load()}catch(error){showToast('Acceso rechazado',error.message)}});
document.querySelector('#refreshButton').addEventListener('click',()=>load().catch(error=>showToast('No se pudo actualizar',error.message)));
const adminPasswordForm=document.querySelector('#adminPasswordForm');
document.querySelector('#securityButton').addEventListener('click',()=>{adminPasswordForm.hidden=!adminPasswordForm.hidden});
adminPasswordForm.addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;if(!form.checkValidity())return form.reportValidity();const submit=form.querySelector('[type="submit"]');submit.disabled=true;try{await api('/api/auth/change-password',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});form.reset();panel.hidden=true;login.hidden=false;showToast('Contraseña actualizada','Todas las sesiones quedaron cerradas. Ingresa con la nueva contraseña.')}catch(error){showToast('No se pudo cambiar',error.message)}finally{submit.disabled=false}});
function escapeHtml(value){const element=document.createElement('span');element.textContent=String(value??'');return element.innerHTML}
api('/api/auth/me').then(user=>{if(user.role==='admin')return load();throw new Error('no-admin')}).catch(()=>{});
